let _db: ReturnType<typeof drizzle> | null = null;
export async function getDb() { if (!_db && process.env.DATABASE_URL) { try { _db = drizzle(process.env.DATABASE_URL); } catch (error) { console.warn("[Database] Failed to connect:", error); _db = null; } } return _db; }

export async function upsertUser(user: InsertUser): Promise<void> { if (!user.openId) throw new Error("User openId is required for upsert"); const db = await getDb(); if (!db) return; const values: InsertUser = { openId: user.openId }; const updateSet: Record<string, unknown> = {}; for (const field of ["name", "email", "loginMethod"] as const) { if (user[field] !== undefined) { values[field] = user[field] ?? null; updateSet[field] = user[field] ?? null; } } values.lastSignedIn = user.lastSignedIn ?? new Date(); updateSet.lastSignedIn = values.lastSignedIn; if (user.role) { values.role = user.role; updateSet.role = user.role; } else if (user.openId === ENV.ownerOpenId) { values.role = "admin"; updateSet.role = "admin"; } await db.insert(users).values(values).onDuplicateKeyUpdate({ set: updateSet }); }
export async function getUserByOpenId(openId: string) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(users).where(eq(users.openId, openId)).limit(1); return result[0]; }
export async function getUserById(id: number) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(users).where(eq(users.id, id)).limit(1); return result[0]; }

export async function getTeacherProfile(userId: number) { const db = await getDb(); if (!db) return undefined; const result = await db.select().from(teacherProfiles).where(eq(teacherProfiles.userId, userId)).limit(1); return result[0]; }
export async function updateTeacherAvatar(userId: number, avatarUrl: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(teacherProfiles).set({ avatarUrl }).where(eq(teacherProfiles.userId, userId)); await recordChange(userId, { category: "settings", action: "updated", entityName: "الصورة الشخصية", details: "تم تحديث صورة ملف المعلم" }); return getTeacherProfile(userId); }
export async function recordChange(userId: number, input: Omit<typeof changeLogs.$inferInsert, "id" | "userId" | "createdAt">) { const db = await getDb(); if (!db) return; try { await db.insert(changeLogs).values({ ...input, userId }); } catch (error) { console.warn("[ChangeLog] Failed to record change", error); } }
export async function listChangeLogs(userId: number, limit = 80) { const db = await getDb(); if (!db) return []; return db.select().from(changeLogs).where(eq(changeLogs.userId, userId)).orderBy(desc(changeLogs.createdAt)).limit(limit); }
export async function saveTeacherProfile(userId: number, input: Omit<InsertTeacherProfile, "userId">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.insert(teacherProfiles).values({ ...input, userId }).onDuplicateKeyUpdate({ set: input }); await recordChange(userId, { category: "settings", action: "updated", entityName: "إعدادات الحساب", details: "تم حفظ إعدادات المعلم" }); return getTeacherProfile(userId); }
export async function getSchoolWorkspace(userId: number) { const profile = await getTeacherProfile(userId); return { schoolScheduleJson: profile?.schoolScheduleJson ?? null, weeklyEvaluationJson: profile?.weeklyEvaluationJson ?? null }; }
export async function ensureOwnedGroupInWorkspace(userId: number, workspace: Workspace, groupId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const group = (await db.select({ id: studyGroups.id }).from(studyGroups).where(and(eq(studyGroups.id, groupId), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1))[0]; if (!group) throw new Error("GROUP_NOT_FOUND"); return group; }
export async function listLearningMaterials(userId: number, groupId?: number, workspace: Workspace = "center") { const db = await getDb(); if (!db) return []; if (groupId) await ensureOwnedGroupInWorkspace(userId, workspace, groupId); const scopedGroupIds = db.select({ id: studyGroups.id }).from(studyGroups).where(and(eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))); const where = groupId ? and(eq(learningMaterials.userId, userId), eq(learningMaterials.groupId, groupId)) : and(eq(learningMaterials.userId, userId), inArray(learningMaterials.groupId, scopedGroupIds)); return db.select().from(learningMaterials).where(where).orderBy(desc(learningMaterials.createdAt)); }
export async function createLearningMaterial(userId: number, input: Omit<typeof learningMaterials.$inferInsert, "id" | "userId" | "createdAt">, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedGroupInWorkspace(userId, workspace, input.groupId); const result = await db.insert(learningMaterials).values({ ...input, userId }); return Number(result[0].insertId); }
export async function listStudentLearningMaterials(studentId: number) { const db = await getDb(); if (!db) return []; const record = await db.select({ userId: students.userId, groupId: students.groupId }).from(students).where(eq(students.id, studentId)).limit(1); const student = record[0]; if (!student?.groupId) return []; return db.select().from(learningMaterials).where(and(eq(learningMaterials.userId, student.userId), eq(learningMaterials.groupId, student.groupId))).orderBy(desc(learningMaterials.createdAt)); }
export async function listVideoLessons(userId: number, groupId: number, workspace: Workspace = "center") { const db = await getDb(); if (!db) return []; await ensureOwnedGroupInWorkspace(userId, workspace, groupId); return db.select().from(videoLessons).where(and(eq(videoLessons.userId, userId), eq(videoLessons.groupId, groupId))).orderBy(desc(videoLessons.createdAt)); }
