export async function listStudentVideoLessons(studentId: number) { const access = await getStudentGroupAccess(studentId); const db = await getDb(); if (!access || !db) return []; return db.select().from(videoLessons).where(and(eq(videoLessons.userId, access.userId), eq(videoLessons.groupId, access.groupId), eq(videoLessons.status, "published"))).orderBy(desc(videoLessons.publishedAt), desc(videoLessons.createdAt)); }

export async function listGroupDiscussion(userId: number, groupId: number, workspace: Workspace = "center") { const db = await getDb(); if (!db) return []; await ensureOwnedGroupInWorkspace(userId, workspace, groupId); return db.select().from(groupDiscussionMessages).where(and(eq(groupDiscussionMessages.userId, userId), eq(groupDiscussionMessages.groupId, groupId), isNull(groupDiscussionMessages.deletedAt))).orderBy(groupDiscussionMessages.createdAt); }
export async function postTeacherDiscussionMessage(userId: number, groupId: number, body: string, authorType: "teacher" | "assistant" = "teacher", workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedGroupInWorkspace(userId, workspace, groupId); const result = await db.insert(groupDiscussionMessages).values({ userId, groupId, authorType, body: body.trim() }); return Number(result[0].insertId); }
export async function getStudentGroupAccess(studentId: number) { const db = await getDb(); if (!db) return null; const row = (await db.select({ id: students.id, userId: students.userId, groupId: students.groupId, workspace: students.workspace }).from(students).where(eq(students.id, studentId)).limit(1))[0]; if (!row || row.groupId === null) return null; return { id: row.id, userId: row.userId, groupId: row.groupId, workspace: row.workspace }; }
function hashBrowserDeviceId(value: string) { return createHash("sha256").update(value).digest("hex"); }
export async function getStudentDeviceBinding(studentId: number) { const db = await getDb(); if (!db) return undefined; return (await db.select().from(studentDeviceBindings).where(eq(studentDeviceBindings.studentId, studentId)).limit(1))[0]; }
export async function bindStudentBrowserDevice(studentId: number, deviceId: string, deviceName: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const deviceIdHash = hashBrowserDeviceId(deviceId); const existing = await getStudentDeviceBinding(studentId); if (!existing) { await db.insert(studentDeviceBindings).values({ studentId, deviceIdHash, deviceName: deviceName.slice(0, 220) }); return { status: "bound" as const }; } if (existing.status === "release_requested") throw new Error("DEVICE_RELEASE_REQUESTED"); if (existing.deviceIdHash !== deviceIdHash) throw new Error("DEVICE_BOUND_TO_ANOTHER_BROWSER"); await db.update(studentDeviceBindings).set({ deviceName: deviceName.slice(0, 220), lastSeenAt: new Date() }).where(eq(studentDeviceBindings.id, existing.id)); return { status: "verified" as const }; }
export async function requestStudentDeviceRelease(studentId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const binding = await getStudentDeviceBinding(studentId); if (!binding) return false; await db.update(studentDeviceBindings).set({ status: "release_requested", releaseRequestedAt: new Date() }).where(eq(studentDeviceBindings.id, binding.id)); return true; }
export async function listTeacherStudentDeviceBindings(userId: number) { const db = await getDb(); if (!db) return []; return db.select({ id: studentDeviceBindings.id, studentId: studentDeviceBindings.studentId, deviceName: studentDeviceBindings.deviceName, status: studentDeviceBindings.status, releaseRequestedAt: studentDeviceBindings.releaseRequestedAt, boundAt: studentDeviceBindings.boundAt, lastSeenAt: studentDeviceBindings.lastSeenAt, studentName: students.name }).from(studentDeviceBindings).innerJoin(students, eq(students.id, studentDeviceBindings.studentId)).where(eq(students.userId, userId)).orderBy(desc(studentDeviceBindings.lastSeenAt)); }
export async function releaseTeacherStudentDeviceBinding(userId: number, studentId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const student = (await db.select({ id: students.id }).from(students).where(and(eq(students.id, studentId), eq(students.userId, userId))).limit(1))[0]; if (!student) throw new Error("STUDENT_NOT_FOUND"); await db.delete(studentDeviceBindings).where(eq(studentDeviceBindings.studentId, studentId)); return true; }
export async function listStudentGroupDiscussion(studentId: number) { const access = await getStudentGroupAccess(studentId); return access ? listGroupDiscussion(access.userId, access.groupId, access.workspace) : []; }
export async function postStudentDiscussionMessage(studentId: number, body: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const access = await getStudentGroupAccess(studentId); if (!access) throw new Error("STUDENT_GROUP_NOT_FOUND"); const result = await db.insert(groupDiscussionMessages).values({ userId: access.userId, groupId: access.groupId, authorType: "student", authorStudentId: studentId, body: body.trim() }); return Number(result[0].insertId); }
