export async function listGroupNotes(userId: number, groupId: number, workspace: Workspace = "center") { const db = await getDb(); if (!db) return []; await ensureOwnedGroupInWorkspace(userId, workspace, groupId); return db.select().from(groupNotes).where(and(eq(groupNotes.userId, userId), eq(groupNotes.groupId, groupId))).orderBy(desc(groupNotes.completed), desc(groupNotes.refreshedAt)); }
export async function createGroupNote(userId: number, input: { groupId: number; body: string }, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedGroupInWorkspace(userId, workspace, input.groupId); const result = await db.insert(groupNotes).values({ userId, groupId: input.groupId, body: input.body.trim() }); return Number(result[0].insertId); }
export async function updateGroupNote(userId: number, workspace: Workspace, id: number, input: { completed?: boolean; renew?: boolean }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const note = (await db.select({ groupId: groupNotes.groupId }).from(groupNotes).where(and(eq(groupNotes.id, id), eq(groupNotes.userId, userId))).limit(1))[0]; if (!note) throw new Error("GROUP_NOTE_NOT_FOUND"); await ensureOwnedGroupInWorkspace(userId, workspace, note.groupId); const update = input.renew ? { completed: false, refreshedAt: new Date() } : { completed: Boolean(input.completed) }; await db.update(groupNotes).set(update).where(and(eq(groupNotes.id, id), eq(groupNotes.userId, userId))); return true; }
export async function deleteGroupNote(userId: number, workspace: Workspace, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const note = (await db.select({ groupId: groupNotes.groupId }).from(groupNotes).where(and(eq(groupNotes.id, id), eq(groupNotes.userId, userId))).limit(1))[0]; if (!note) throw new Error("GROUP_NOTE_NOT_FOUND"); await ensureOwnedGroupInWorkspace(userId, workspace, note.groupId); await db.delete(groupNotes).where(and(eq(groupNotes.id, id), eq(groupNotes.userId, userId))); return true; }
export async function createGroupAnnouncement(userId: number, input: { groupId: number; title: string; body: string; audience: "students" | "guardians" | "all" }, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedGroupInWorkspace(userId, workspace, input.groupId); const result = await db.insert(groupAnnouncements).values({ userId, ...input }); await recordChange(userId, { category: "group", action: "recorded", entityName: input.title, details: "تم نشر تنبيه للمجموعة" }); return Number(result[0].insertId); }
export async function listStudentGroupAnnouncements(studentId: number) { const access = await getStudentGroupAccess(studentId); return access ? listGroupAnnouncements(access.userId, access.groupId, access.workspace) : []; }
export async function createAssignment(userId: number, input: { groupId: number; title: string; instructions?: string | null; dueAt?: Date | null; status: "draft" | "published" | "closed" }, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedGroupInWorkspace(userId, workspace, input.groupId); const result = await db.insert(assignments).values({ userId, ...input }); return Number(result[0].insertId); }
export async function listGroupAssignments(userId: number, groupId: number, workspace: Workspace = "center") { const db = await getDb(); if (!db) return []; await ensureOwnedGroupInWorkspace(userId, workspace, groupId); return db.select().from(assignments).where(and(eq(assignments.userId, userId), eq(assignments.groupId, groupId))).orderBy(desc(assignments.createdAt)); }
export async function listStudentAssignments(studentId: number) { const access = await getStudentGroupAccess(studentId); if (!access) return []; const db = await getDb(); if (!db) return []; return db.select().from(assignments).where(and(eq(assignments.userId, access.userId), eq(assignments.groupId, access.groupId), eq(assignments.status, "published"))).orderBy(desc(assignments.createdAt)); }
export async function saveAssignmentSubmission(userId: number, input: { assignmentId: number; studentId: number; storageKey: string; storageUrl: string; mimeType: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const assignment = (await db.select().from(assignments).where(and(eq(assignments.id, input.assignmentId), eq(assignments.userId, userId), eq(assignments.status, "published"))).limit(1))[0]; const student = (await db.select({ groupId: students.groupId }).from(students).where(and(eq(students.id, input.studentId), eq(students.userId, userId))).limit(1))[0]; if (!assignment || !student || !canStudentAccessGroup(student.groupId, assignment.groupId)) throw new Error("ASSIGNMENT_NOT_AVAILABLE"); await db.insert(assignmentSubmissions).values({ ...input, userId }).onDuplicateKeyUpdate({ set: { storageKey: input.storageKey, storageUrl: input.storageUrl, mimeType: input.mimeType, status: "submitted", reviewNote: null, score: null, submittedAt: new Date(), reviewedAt: null } }); return true; }
export async function listAssignmentSubmissions(userId: number, assignmentId: number) { const db = await getDb(); if (!db) return []; return db.select({ id: assignmentSubmissions.id, assignmentId: assignmentSubmissions.assignmentId, studentId: assignmentSubmissions.studentId, storageUrl: assignmentSubmissions.storageUrl, mimeType: assignmentSubmissions.mimeType, status: assignmentSubmissions.status, score: assignmentSubmissions.score, reviewNote: assignmentSubmissions.reviewNote, submittedAt: assignmentSubmissions.submittedAt, reviewedAt: assignmentSubmissions.reviewedAt, studentName: students.name }).from(assignmentSubmissions).innerJoin(students, eq(students.id, assignmentSubmissions.studentId)).where(and(eq(assignmentSubmissions.userId, userId), eq(assignmentSubmissions.assignmentId, assignmentId), eq(students.userId, userId))).orderBy(desc(assignmentSubmissions.submittedAt)); }
export async function reviewAssignmentSubmission(userId: number, id: number, input: { score?: string | null; reviewNote?: string | null }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(assignmentSubmissions).set({ score: input.score ?? null, reviewNote: input.reviewNote ?? null, status: "reviewed", reviewedAt: new Date() }).where(and(eq(assignmentSubmissions.id, id), eq(assignmentSubmissions.userId, userId))); return true; }
export async function saveSchoolWorkspace(userId: number, input: { schoolScheduleJson: string; weeklyEvaluationJson: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.update(teacherProfiles).set(input).where(eq(teacherProfiles.userId, userId)); await recordChange(userId, { category: "settings", action: "updated", entityName: "وضع المدرسة", details: "تم تحديث جدول اليوم والتقييم الأسبوعي" }); return getSchoolWorkspace(userId); }

export async function listYearWorkTerms(userId: number) { const db = await getDb(); if (!db) return []; return db.select().from(yearWorkTerms).where(eq(yearWorkTerms.userId, userId)).orderBy(desc(yearWorkTerms.updatedAt)); }
export async function getYearWorkWorkspace(userId: number, termId?: number) { const db = await getDb(); if (!db) return { terms: [], scores: [], attendance: [] }; const terms = await listYearWorkTerms(userId); const selectedTermId = termId && terms.some(term => term.id === termId) ? termId : terms[0]?.id; if (!selectedTermId) return { terms, scores: [], attendance: [] }; const selected = terms.find(term => term.id === selectedTermId); const [scores, attendanceRows] = await Promise.all([db.select().from(yearWorkScores).where(and(eq(yearWorkScores.userId, userId), eq(yearWorkScores.termId, selectedTermId))), selected ? db.select().from(attendance).where(and(eq(attendance.userId, userId), gte(attendance.lessonDate, selected.startsAt), lte(attendance.lessonDate, selected.endsAt))) : Promise.resolve([])]); return { terms, scores, attendance: attendanceRows };
}
export async function saveYearWorkTerm(userId: number, input: { id?: number; term: "first" | "second"; grade: string; startsAt: Date; endsAt: Date; monthsJson: string; studentIdsJson: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const values = { term: input.term, grade: input.grade, startsAt: input.startsAt, endsAt: input.endsAt, monthsJson: input.monthsJson, studentIdsJson: input.studentIdsJson }; if (input.id) { const owned = await db.select({ id: yearWorkTerms.id }).from(yearWorkTerms).where(and(eq(yearWorkTerms.id, input.id), eq(yearWorkTerms.userId, userId))).limit(1); if (!owned[0]) throw new Error("YEAR_WORK_TERM_NOT_FOUND"); await db.update(yearWorkTerms).set(values).where(and(eq(yearWorkTerms.id, input.id), eq(yearWorkTerms.userId, userId))); await recordChange(userId, { category: "assessment", action: "updated", entityName: `أعمال السنة: ${input.grade}`, details: "تم تحديث إعدادات الفصل الدراسي" }); return input.id; }
  const result = await db.insert(yearWorkTerms).values({ ...values, userId }); const id = Number(result[0].insertId); await recordChange(userId, { category: "assessment", action: "created", entityName: `أعمال السنة: ${input.grade}`, details: "تم إنشاء سجل أعمال سنة" }); return id;
}
export async function saveYearWorkScore(userId: number, input: { termId: number; studentId: number; monthKey: string; homeWork: number; activity: number; weeklyEvaluation: number; performanceTasks: number; behavior: number; attendance: number; monthlyExam: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const [term, student] = await Promise.all([db.select({ id: yearWorkTerms.id }).from(yearWorkTerms).where(and(eq(yearWorkTerms.id, input.termId), eq(yearWorkTerms.userId, userId))).limit(1), db.select({ id: students.id, name: students.name }).from(students).where(and(eq(students.id, input.studentId), eq(students.userId, userId))).limit(1)]); if (!term[0] || !student[0]) throw new Error("YEAR_WORK_NOT_FOUND"); const values = { ...input, userId }; await db.insert(yearWorkScores).values(values).onDuplicateKeyUpdate({ set: { homeWork: input.homeWork, activity: input.activity, weeklyEvaluation: input.weeklyEvaluation, performanceTasks: input.performanceTasks, behavior: input.behavior, attendance: input.attendance, monthlyExam: input.monthlyExam } }); await recordChange(userId, { category: "assessment", action: "recorded", entityName: student[0].name, details: `تم رصد أعمال السنة لشهر ${input.monthKey}` }); return true;
}

export async function listGroups(userId: number, workspace?: Workspace) { const db = await getDb(); if (!db) return []; return db.select().from(studyGroups).where(workspace ? and(eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace)) : eq(studyGroups.userId, userId)).orderBy(desc(studyGroups.createdAt)); }
export async function createGroup(userId: number, workspace: Workspace, input: Omit<InsertStudyGroup, "userId" | "id" | "workspace">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const result = await db.insert(studyGroups).values({ ...input, workspace, userId }); await recordChange(userId, { category: "group", action: "created", entityName: input.name, details: `تم إنشاء مجموعة ${input.place}` }); return { id: Number(result[0].insertId), ...input, workspace, userId }; }
export async function updateGroup(userId: number, workspace: Workspace, id: number, input: Partial<Omit<InsertStudyGroup, "userId" | "id" | "workspace">>) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ name: studyGroups.name }).from(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1); if (!before[0]) throw new Error("GROUP_NOT_FOUND"); await db.update(studyGroups).set(input).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))); await recordChange(userId, { category: "group", action: "updated", entityName: input.name || before[0].name, details: "تم تعديل بيانات المجموعة" }); return true; }
export async function deleteGroup(userId: number, workspace: Workspace, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ name: studyGroups.name }).from(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1); if (!before[0]) throw new Error("GROUP_NOT_FOUND"); await db.delete(studyGroups).where(and(eq(studyGroups.id, id), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))); await recordChange(userId, { category: "group", action: "deleted", entityName: before[0].name, details: "تم حذف المجموعة" }); return true; }


export async function listStudents(userId: number, workspace?: Workspace) { const db = await getDb(); if (!db) return []; return db.select().from(students).where(workspace ? and(eq(students.userId, userId), eq(students.workspace, workspace)) : eq(students.userId, userId)).orderBy(desc(students.createdAt)); }
	async function adjustGroupStudentCount(userId: number, workspace: Workspace, groupId: number | null | undefined, delta: number) { const db = await getDb(); if (!db || !groupId || !delta) return; await db.update(studyGroups).set({ studentsCount: sql`GREATEST(0, ${studyGroups.studentsCount} + ${delta})` }).where(and(eq(studyGroups.id, groupId), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))); }

export async function createStudent(userId: number, workspace: Workspace, input: Omit<InsertStudent, "userId" | "id" | "joinedGroupAt" | "workspace">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const groupRows = input.groupId ? await db.select({ fee: studyGroups.fee }).from(studyGroups).where(and(eq(studyGroups.id, input.groupId), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1) : []; if (input.groupId && !groupRows[0]) throw new Error("GROUP_NOT_FOUND"); const paidAmount = Number(input.paidAmount || 0); const fee = Number(groupRows[0]?.fee || 0); const paid = fee > 0 ? paidAmount >= fee : Boolean(input.paid); const joinedGroupAt = new Date(); const result = await db.insert(students).values({ ...input, workspace, joinedGroupAt, paidAmount: String(Math.max(0, paidAmount)), paid, userId }); const studentId = Number(result[0].insertId); if (paidAmount > 0) await db.insert(financialTransactions).values({ userId, workspace, studentId, groupId: input.groupId ?? null, kind: "subscription", amount: String(paidAmount), paidAt: new Date(), dueDate: null, description: "دفعة تسجيل الطالب" }); await adjustGroupStudentCount(userId, workspace, input.groupId, 1); await recordChange(userId, { category: "student", action: "created", entityName: input.name, details: "تم تسجيل طالب جديد" }); return { id: studentId, ...input, workspace, joinedGroupAt, paidAmount: String(Math.max(0, paidAmount)), paid, userId }; }
export async function updateStudent(userId: number, workspace: Workspace, id: number, input: Partial<Omit<InsertStudent, "userId" | "id" | "joinedGroupAt" | "workspace">>) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ groupId: students.groupId, name: students.name }).from(students).where(and(eq(students.id, id), eq(students.userId, userId), eq(students.workspace, workspace))).limit(1); if (!before[0]) throw new Error("STUDENT_NOT_FOUND"); const targetGroupId = input.groupId === undefined ? before[0].groupId : input.groupId; const groupRows = targetGroupId ? await db.select({ fee: studyGroups.fee }).from(studyGroups).where(and(eq(studyGroups.id, targetGroupId), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1) : []; if (targetGroupId && !groupRows[0]) throw new Error("GROUP_NOT_FOUND"); const nextAmount = input.paidAmount === undefined ? undefined : Math.max(0, Number(input.paidAmount)); const groupChanged = input.groupId !== undefined && input.groupId !== before[0].groupId; const nextValues = { ...(nextAmount === undefined ? input : { ...input, paidAmount: String(nextAmount), paid: Number(groupRows[0]?.fee || 0) > 0 ? nextAmount >= Number(groupRows[0]?.fee || 0) : Boolean(input.paid) }), ...(groupChanged ? { joinedGroupAt: new Date() } : {}) }; await db.update(students).set(nextValues).where(and(eq(students.id, id), eq(students.userId, userId), eq(students.workspace, workspace))); if (groupChanged) { await adjustGroupStudentCount(userId, workspace, before[0].groupId, -1); await adjustGroupStudentCount(userId, workspace, input.groupId, 1); } await recordChange(userId, { category: "student", action: "updated", entityName: input.name || before[0].name, details: "تم تعديل بيانات الطالب" }); return true; }
export async function deleteStudent(userId: number, workspace: Workspace, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const before = await db.select({ groupId: students.groupId, name: students.name }).from(students).where(and(eq(students.id, id), eq(students.userId, userId), eq(students.workspace, workspace))).limit(1); if (!before[0]) throw new Error("STUDENT_NOT_FOUND"); await db.delete(students).where(and(eq(students.id, id), eq(students.userId, userId), eq(students.workspace, workspace))); await adjustGroupStudentCount(userId, workspace, before[0].groupId, -1); await recordChange(userId, { category: "student", action: "deleted", entityName: before[0].name, details: "تم حذف الطالب" }); return true; }

export function normalizeStudentPhone(value: string) { const arabicDigits = "٠١٢٣٤٥٦٧٨٩"; return value.trim().replace(/[٠-٩]/g, digit => String(arabicDigits.indexOf(digit))).replace(/[^0-9+]/g, ""); }
export const normalizeTeacherPhone = normalizeStudentPhone;
export async function getTeacherAccountByPhone(phone: string) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(teacherAccounts).where(eq(teacherAccounts.phone, normalizeTeacherPhone(phone))).limit(1); return rows[0]; }
export async function getTeacherAccountByUserId(userId: number) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(teacherAccounts).where(eq(teacherAccounts.userId, userId)).limit(1); return rows[0]; }
export async function createPhoneTeacher(input: { name: string; phone: string; subject: string; passwordHash: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const phone = normalizeTeacherPhone(input.phone); const existing = await getTeacherAccountByPhone(phone); if (existing) throw new Error("TEACHER_PHONE_EXISTS"); const userResult = await db.insert(users).values({ openId: `phone:${phone}`, name: input.name, loginMethod: "phone", lastSignedIn: new Date() }); const userId = Number(userResult[0].insertId); await db.insert(teacherProfiles).values({ userId, name: input.name, phone, subject: input.subject }); const accountResult = await db.insert(teacherAccounts).values({ userId, phone, passwordHash: input.passwordHash }); return { id: Number(accountResult[0].insertId), userId, phone }; }
export async function upsertTeacherAccount(userId: number, phone: string, passwordHash: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const normalizedPhone = normalizeTeacherPhone(phone); const existing = await db.select().from(teacherAccounts).where(eq(teacherAccounts.userId, userId)).limit(1); if (existing[0]) { await db.update(teacherAccounts).set({ phone: normalizedPhone, passwordHash, lastSignedIn: new Date() }).where(eq(teacherAccounts.id, existing[0].id)); return { id: existing[0].id, userId, phone: normalizedPhone }; } const result = await db.insert(teacherAccounts).values({ userId, phone: normalizedPhone, passwordHash }); return { id: Number(result[0].insertId), userId, phone: normalizedPhone }; }
export async function touchTeacherAccount(accountId: number) { const db = await getDb(); if (!db) return; await db.update(teacherAccounts).set({ lastSignedIn: new Date() }).where(eq(teacherAccounts.id, accountId)); }
export async function findStudentByPhone(userId: number, phone: string) { const db = await getDb(); if (!db) return undefined; const target = normalizeStudentPhone(phone); const rows = await db.select().from(students).where(eq(students.userId, userId)); return rows.find(row => row.phone && normalizeStudentPhone(row.phone) === target); }
export async function getStudentAccountByPhone(userId: number, phone: string) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(studentAccounts).where(and(eq(studentAccounts.userId, userId), eq(studentAccounts.phone, normalizeStudentPhone(phone)))).limit(1); return rows[0]; }
export async function getStudentAccountById(id: number) { const db = await getDb(); if (!db) return undefined; const rows = await db.select().from(studentAccounts).where(eq(studentAccounts.id, id)).limit(1); return rows[0]; }
export async function createStudentAccount(userId: number, studentId: number, phone: string, passwordHash: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const normalizedPhone = normalizeStudentPhone(phone); const result = await db.insert(studentAccounts).values({ userId, studentId, phone: normalizedPhone, passwordHash }); return { id: Number(result[0].insertId), userId, studentId, phone: normalizedPhone, passwordHash }; }
export async function touchStudentAccount(accountId: number) { const db = await getDb(); if (!db) return; await db.update(studentAccounts).set({ lastSignedIn: new Date() }).where(eq(studentAccounts.id, accountId)); }
export async function getParentAccountByPhone(userId: number, phone: string) { const db = await getDb(); if (!db) return undefined; return (await db.select().from(parentAccounts).where(and(eq(parentAccounts.userId, userId), eq(parentAccounts.phone, normalizeStudentPhone(phone)))).limit(1))[0]; }
export async function getParentAccountById(id: number, userId: number) { const db = await getDb(); if (!db) return undefined; return (await db.select().from(parentAccounts).where(and(eq(parentAccounts.id, id), eq(parentAccounts.userId, userId))).limit(1))[0]; }
export async function findGuardianStudents(userId: number, phone: string) { const db = await getDb(); if (!db) return []; const normalized = normalizeStudentPhone(phone); const rows = await db.select().from(students).where(eq(students.userId, userId)); return rows.filter(student => student.guardianPhone && normalizeStudentPhone(student.guardianPhone) === normalized); }
export async function createParentAccountForGuardian(userId: number, phone: string, passwordHash: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const matched = await findGuardianStudents(userId, phone); if (!matched.length) throw new Error("GUARDIAN_PHONE_NOT_FOUND"); const normalizedPhone = normalizeStudentPhone(phone); const existing = await getParentAccountByPhone(userId, normalizedPhone); if (existing) throw new Error("PARENT_ACCOUNT_EXISTS"); const result = await db.insert(parentAccounts).values({ userId, phone: normalizedPhone, passwordHash }); const accountId = Number(result[0].insertId); for (const student of matched) await db.insert(parentStudentLinks).values({ parentId: accountId, studentId: student.id }); return { id: accountId, userId, phone: normalizedPhone }; }
export async function touchParentAccount(accountId: number) { const db = await getDb(); if (!db) return; await db.update(parentAccounts).set({ lastSignedIn: new Date() }).where(eq(parentAccounts.id, accountId)); }
export async function getParentPortalData(parentId: number, userId: number) { const db = await getDb(); if (!db) return null; const parent = await getParentAccountById(parentId, userId); if (!parent) return null; const linked = await db.select({ student: students, groupName: studyGroups.name }).from(parentStudentLinks).innerJoin(students, eq(students.id, parentStudentLinks.studentId)).leftJoin(studyGroups, eq(studyGroups.id, students.groupId)).where(and(eq(parentStudentLinks.parentId, parentId), eq(students.userId, userId))); const children = await Promise.all(linked.map(async ({ student, groupName }) => ({ student, groupName: groupName || null, attendance: await db.select().from(attendance).where(and(eq(attendance.userId, userId), eq(attendance.studentId, student.id))).orderBy(desc(attendance.lessonDate)).limit(40), assessments: await db.select().from(assessments).where(and(eq(assessments.userId, userId), eq(assessments.studentId, student.id))).orderBy(desc(assessments.createdAt)).limit(30), transactions: await db.select().from(financialTransactions).where(and(eq(financialTransactions.userId, userId), eq(financialTransactions.studentId, student.id))).orderBy(desc(financialTransactions.createdAt)).limit(30) }))); return { parent: { id: parent.id, phone: parent.phone, lastSignedIn: parent.lastSignedIn }, children }; }
function roomSeats(room: { capacity: number; seatMapJson?: string | null }) { try { const values = JSON.parse(room.seatMapJson || "[]"); if (Array.isArray(values) && values.every(value => typeof value === "string") && values.length) return values.map(value => value.trim()).filter(Boolean).slice(0, room.capacity); } catch {} return Array.from({ length: room.capacity }, (_, index) => String(index + 1)); }
export async function listCenterRooms(userId: number) { const db = await getDb(); if (!db) return []; const rooms = await db.select().from(centerRooms).where(eq(centerRooms.userId, userId)).orderBy(centerRooms.name); return rooms.map(room => ({ ...room, seats: roomSeats(room) })); }
export async function createCenterRoom(userId: number, input: { name: string; capacity: number; seatMap?: string[] }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const seats = input.seatMap?.map(value => value.trim()).filter(Boolean) || []; if (seats.length && (new Set(seats).size !== seats.length || seats.length > input.capacity)) throw new Error("INVALID_SEAT_MAP"); const result = await db.insert(centerRooms).values({ userId, name: input.name.trim(), capacity: input.capacity, seatMapJson: seats.length ? JSON.stringify(seats) : null }); return Number(result[0].insertId); }
export async function listRoomReservations(userId: number, roomId: number, sessionAt: Date) { const db = await getDb(); if (!db) return []; const room = (await db.select().from(centerRooms).where(and(eq(centerRooms.id, roomId), eq(centerRooms.userId, userId))).limit(1))[0]; if (!room) throw new Error("ROOM_NOT_FOUND"); return db.select({ id: seatReservations.id, groupId: seatReservations.groupId, studentId: seatReservations.studentId, seatNumber: seatReservations.seatNumber, status: seatReservations.status, sessionAt: seatReservations.sessionAt, studentName: students.name }).from(seatReservations).innerJoin(students, eq(students.id, seatReservations.studentId)).where(and(eq(seatReservations.userId, userId), eq(seatReservations.roomId, roomId), eq(seatReservations.sessionAt, sessionAt))).orderBy(seatReservations.seatNumber); }
export async function getStudentSeatAvailability(studentId: number, sessionAt: Date) { const access = await getStudentGroupAccess(studentId); if (!access) return { groupId: null, rooms: [] as Array<Record<string, unknown>>, ownReservation: null }; const rooms = await listCenterRooms(access.userId); const db = await getDb(); if (!db) return { groupId: access.groupId, rooms, ownReservation: null }; const reservations = await db.select().from(seatReservations).where(and(eq(seatReservations.userId, access.userId), eq(seatReservations.sessionAt, sessionAt))); const ownReservation = reservations.find(row => row.studentId === studentId && row.status === "reserved") || null; return { groupId: access.groupId, rooms: rooms.map(room => ({ ...room, reservedSeats: reservations.filter(row => row.roomId === room.id && row.status === "reserved").map(row => row.seatNumber) })), ownReservation };
}
export async function reserveStudentSeat(studentId: number, input: { roomId: number; seatNumber: string; sessionAt: Date }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const access = await getStudentGroupAccess(studentId); if (!access) throw new Error("STUDENT_GROUP_NOT_FOUND"); const room = (await db.select().from(centerRooms).where(and(eq(centerRooms.id, input.roomId), eq(centerRooms.userId, access.userId))).limit(1))[0]; if (!room) throw new Error("ROOM_NOT_FOUND"); const seatNumber = input.seatNumber.trim(); if (!roomSeats(room).includes(seatNumber)) throw new Error("SEAT_NOT_FOUND"); const existing = (await db.select().from(seatReservations).where(and(eq(seatReservations.studentId, studentId), eq(seatReservations.sessionAt, input.sessionAt))).limit(1))[0]; if (existing) throw new Error("STUDENT_ALREADY_RESERVED"); try { const result = await db.insert(seatReservations).values({ userId: access.userId, groupId: access.groupId, roomId: room.id, studentId, sessionAt: input.sessionAt, seatNumber, status: "reserved" }); return Number(result[0].insertId); } catch { throw new Error("SEAT_ALREADY_RESERVED"); } }
export async function cancelStudentSeatReservation(studentId: number, reservationId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.delete(seatReservations).where(and(eq(seatReservations.id, reservationId), eq(seatReservations.studentId, studentId), eq(seatReservations.status, "reserved"))); return true; }
export async function listStoreProducts(userId: number, activeOnly = false) { const db = await getDb(); if (!db) return []; const where = activeOnly ? and(eq(storeProducts.userId, userId), eq(storeProducts.active, true)) : eq(storeProducts.userId, userId); return db.select().from(storeProducts).where(where).orderBy(desc(storeProducts.createdAt)); }
export async function createStoreProduct(userId: number, input: { title: string; description?: string | null; price: string; stockQuantity: number; fulfillment: "pickup" | "delivery" | "both"; imageUrl?: string | null }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const result = await db.insert(storeProducts).values({ userId, title: input.title.trim(), description: input.description || null, price: input.price, stockQuantity: input.stockQuantity, fulfillment: input.fulfillment, imageUrl: input.imageUrl || null, active: true }); return Number(result[0].insertId); }
export async function updateStoreProduct(userId: number, id: number, input: { active?: boolean; stockQuantity?: number; price?: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const set: { active?: boolean; stockQuantity?: number; price?: string } = {}; if (input.active !== undefined) set.active = input.active; if (input.stockQuantity !== undefined) set.stockQuantity = input.stockQuantity; if (input.price !== undefined) set.price = input.price; await db.update(storeProducts).set(set).where(and(eq(storeProducts.id, id), eq(storeProducts.userId, userId))); return true; }
async function getStudentCommerceContext(studentId: number) { const db = await getDb(); if (!db) return null; return (await db.select({ id: students.id, userId: students.userId, name: students.name }).from(students).where(eq(students.id, studentId)).limit(1))[0] || null; }
export async function listStudentStoreProducts(studentId: number) { const context = await getStudentCommerceContext(studentId); return context ? listStoreProducts(context.userId, true) : []; }
export async function getStudentWalletSummary(studentId: number) { const context = await getStudentCommerceContext(studentId); const db = await getDb(); if (!context || !db) return null; const rows = await db.select().from(walletLedger).where(and(eq(walletLedger.userId, context.userId), eq(walletLedger.studentId, studentId))).orderBy(desc(walletLedger.createdAt)); const balance = rows.reduce((total, row) => total + Number(row.amount), 0); return { balance, entries: rows.slice(0, 30) }; }
export async function generateWalletTopupCode(userId: number, amount: string) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const code = `ELM-${randomBytes(8).toString("hex").toUpperCase()}`; const codeHash = createHash("sha256").update(code).digest("hex"); await db.insert(walletTopupCodes).values({ userId, codeHash, amount, status: "unused" }); return { code, amount }; }
export async function redeemWalletTopupCode(studentId: number, rawCode: string) { const context = await getStudentCommerceContext(studentId); const db = await getDb(); if (!context || !db) throw new Error("STUDENT_NOT_FOUND"); const codeHash = createHash("sha256").update(rawCode.trim().toUpperCase()).digest("hex"); const code = (await db.select().from(walletTopupCodes).where(and(eq(walletTopupCodes.userId, context.userId), eq(walletTopupCodes.codeHash, codeHash))).limit(1))[0]; if (!code || code.status !== "unused") throw new Error("TOPUP_CODE_INVALID"); const update = await db.update(walletTopupCodes).set({ status: "redeemed", redeemedByStudentId: studentId, redeemedAt: new Date() }).where(and(eq(walletTopupCodes.id, code.id), eq(walletTopupCodes.status, "unused"))); if (!Number((update as any)[0]?.affectedRows || 0)) throw new Error("TOPUP_CODE_INVALID"); await db.insert(walletLedger).values({ userId: context.userId, studentId, source: "kiosk_code", amount: code.amount, note: "شحن بكود", referenceKey: `topup:${code.id}` }); return getStudentWalletSummary(studentId); }
export async function listStudentStoreOrders(studentId: number) { const context = await getStudentCommerceContext(studentId); const db = await getDb(); if (!context || !db) return []; return db.select().from(storeOrders).where(and(eq(storeOrders.userId, context.userId), eq(storeOrders.studentId, studentId))).orderBy(desc(storeOrders.createdAt)); }
export async function listTeacherStoreOrders(userId: number) { const db = await getDb(); if (!db) return []; return db.select({ order: storeOrders, studentName: students.name }).from(storeOrders).innerJoin(students, eq(students.id, storeOrders.studentId)).where(and(eq(storeOrders.userId, userId), eq(students.userId, userId))).orderBy(desc(storeOrders.createdAt)); }
export async function createStudentStoreOrder(studentId: number, input: { productId: number; quantity: number; fulfillment: "pickup" | "delivery"; deliveryAddress?: string | null; payWithWallet: boolean }) { const db = await getDb(); const context = await getStudentCommerceContext(studentId); if (!db || !context) throw new Error("STUDENT_NOT_FOUND"); return db.transaction(async tx => { const product = (await tx.select().from(storeProducts).where(and(eq(storeProducts.id, input.productId), eq(storeProducts.userId, context.userId), eq(storeProducts.active, true))).limit(1))[0]; if (!product || product.stockQuantity < input.quantity) throw new Error("PRODUCT_UNAVAILABLE"); if (product.fulfillment !== "both" && product.fulfillment !== input.fulfillment) throw new Error("FULFILLMENT_UNAVAILABLE"); const total = Number(product.price) * input.quantity; if (input.payWithWallet) { const rows = await tx.select().from(walletLedger).where(and(eq(walletLedger.userId, context.userId), eq(walletLedger.studentId, studentId))); const balance = rows.reduce((sum, row) => sum + Number(row.amount), 0); if (balance < total) throw new Error("WALLET_BALANCE_LOW"); }
    const stockUpdate = await tx.update(storeProducts).set({ stockQuantity: sql`${storeProducts.stockQuantity} - ${input.quantity}` }).where(and(eq(storeProducts.id, product.id), eq(storeProducts.userId, context.userId), gte(storeProducts.stockQuantity, input.quantity))); if (!Number((stockUpdate as any)[0]?.affectedRows || 0)) throw new Error("PRODUCT_UNAVAILABLE"); const orderNumber = `ELM-${Date.now().toString(36).toUpperCase()}-${randomBytes(3).toString("hex").toUpperCase()}`; const orderResult = await tx.insert(storeOrders).values({ userId: context.userId, studentId, orderNumber, fulfillment: input.fulfillment, deliveryAddress: input.fulfillment === "delivery" ? input.deliveryAddress || null : null, totalAmount: String(total), status: "pending" }); const orderId = Number(orderResult[0].insertId); await tx.insert(storeOrderItems).values({ orderId, productId: product.id, titleSnapshot: product.title, unitPrice: product.price, quantity: input.quantity }); if (input.payWithWallet) await tx.insert(walletLedger).values({ userId: context.userId, studentId, source: "store_order", amount: String(-total), note: `طلب متجر ${orderNumber}`, referenceKey: `order:${orderId}` }); return { id: orderId, orderNumber, total }; }); }
export async function updateStoreOrderStatus(userId: number, orderId: number, status: "pending" | "confirmed" | "ready" | "out_for_delivery" | "fulfilled" | "cancelled") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); return db.transaction(async tx => { const order = (await tx.select().from(storeOrders).where(and(eq(storeOrders.id, orderId), eq(storeOrders.userId, userId))).limit(1))[0]; if (!order) throw new Error("ORDER_NOT_FOUND"); if (order.status === "cancelled") return true; if (status === "cancelled") { if (order.status === "fulfilled" || order.status === "out_for_delivery") throw new Error("ORDER_CANNOT_CANCEL"); const items = await tx.select().from(storeOrderItems).where(eq(storeOrderItems.orderId, orderId)); for (const item of items) await tx.update(storeProducts).set({ stockQuantity: sql`${storeProducts.stockQuantity} + ${item.quantity}` }).where(and(eq(storeProducts.id, item.productId), eq(storeProducts.userId, userId))); const walletPayment = (await tx.select().from(walletLedger).where(eq(walletLedger.referenceKey, `order:${orderId}`)).limit(1))[0]; if (walletPayment) await tx.insert(walletLedger).values({ userId, studentId: order.studentId, source: "adjustment", amount: String(Math.abs(Number(walletPayment.amount))), note: `استرداد طلب ${order.orderNumber}`, referenceKey: `refund:${orderId}` }); } await tx.update(storeOrders).set({ status }).where(and(eq(storeOrders.id, orderId), eq(storeOrders.userId, userId))); return true; }); }
export type AccountSessionType = "teacher" | "student";
export async function createAccountSession(input: { accountType: AccountSessionType; accountId: number; deviceName: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const id = randomUUID(); await db.insert(accountSessions).values({ id, accountType: input.accountType, accountId: input.accountId, deviceName: input.deviceName.slice(0, 220) || "جهاز غير معروف" }); return id; }
export async function isAccountSessionActive(input: { id: string; accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) return false; const rows = await db.select({ id: accountSessions.id }).from(accountSessions).where(and(eq(accountSessions.id, input.id), eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), isNull(accountSessions.revokedAt))).limit(1); return Boolean(rows[0]); }
export async function listAccountSessions(input: { accountType: AccountSessionType; accountId: number }) { const db = await getDb(); if (!db) return []; return db.select({ id: accountSessions.id, deviceName: accountSessions.deviceName, createdAt: accountSessions.createdAt, lastSeenAt: accountSessions.lastSeenAt }).from(accountSessions).where(and(eq(accountSessions.accountType, input.accountType), eq(accountSessions.accountId, input.accountId), isNull(accountSessions.revokedAt))).orderBy(desc(accountSessions.lastSeenAt)); }
