export async function processRewardRedemption(userId: number, id: number, status: "approved" | "rejected", discountAmount?: string | null) {
  const db = await getDb();
  if (!db) throw new Error("Database unavailable");
  const request = (await db.select().from(rewardRedemptions).where(and(eq(rewardRedemptions.id, id), eq(rewardRedemptions.userId, userId))).limit(1))[0];
  if (!request) throw new Error("REWARD_REQUEST_NOT_FOUND");
  if (request.status !== "pending") throw new Error("REWARD_REQUEST_ALREADY_PROCESSED");
  const creditAmount = Number(discountAmount || 0);
  if (status === "approved") {
    const balance = await getStudentPointBalance(userId, request.studentId);
    if (balance < request.pointsCost) throw new Error("INSUFFICIENT_POINTS");
    if (requiresStudentSubscriptionCredit(request.rewardType) && (!Number.isFinite(creditAmount) || creditAmount <= 0)) throw new Error("DISCOUNT_AMOUNT_REQUIRED");
    await db.insert(studentPointLedger).values({ userId, studentId: request.studentId, source: "redemption", points: -request.pointsCost, note: `استبدال مكافأة: ${request.rewardType}`, referenceKey: `reward:${request.id}` });
    if (requiresStudentSubscriptionCredit(request.rewardType)) await db.insert(studentSubscriptionCredits).values({ userId, studentId: request.studentId, rewardRedemptionId: request.id, amount: String(creditAmount) });
  }
  await db.update(rewardRedemptions).set({ status, discountAmount: requiresStudentSubscriptionCredit(request.rewardType) ? String(creditAmount) : null, processedAt: new Date() }).where(and(eq(rewardRedemptions.id, id), eq(rewardRedemptions.userId, userId), eq(rewardRedemptions.status, "pending")));
  await recordChange(userId, { category: "student", action: "updated", entityName: `طلب مكافأة #${id}`, details: status === "approved" ? "تم اعتماد استبدال النقاط" : "تم رفض طلب استبدال النقاط" });
  return true;
}

export async function collectSubscriptionPayment(userId: number, workspace: Workspace, input: { studentId: number; groupId: number; cashAmount: string }) {
  const db = await getDb();
  if (!db) throw new Error("Database unavailable");
  const [student, group] = await Promise.all([
    db.select().from(students).where(and(eq(students.id, input.studentId), eq(students.userId, userId), eq(students.workspace, workspace))).limit(1),
    db.select().from(studyGroups).where(and(eq(studyGroups.id, input.groupId), eq(studyGroups.userId, userId), eq(studyGroups.workspace, workspace))).limit(1),
  ]);
  const studentRow = student[0]; const groupRow = group[0];
  if (!studentRow || !groupRow || studentRow.groupId !== groupRow.id) throw new Error("STUDENT_GROUP_NOT_FOUND");
  const cashAmount = Number(input.cashAmount);
  const remaining = Math.max(0, Number(groupRow.fee) - Number(studentRow.paidAmount || 0));
  if (!Number.isFinite(cashAmount) || cashAmount < 0 || cashAmount > remaining) throw new Error("INVALID_PAYMENT_AMOUNT");
  const availableCredits = await db.select().from(studentSubscriptionCredits).where(and(eq(studentSubscriptionCredits.userId, userId), eq(studentSubscriptionCredits.studentId, studentRow.id), eq(studentSubscriptionCredits.status, "available"))).orderBy(studentSubscriptionCredits.createdAt);
  const selection = selectApplicableCredits(availableCredits.map(credit => Number(credit.amount)), Math.max(0, remaining - cashAmount));
  const appliedCredits = selection.selectedIndexes.map(index => availableCredits[index]);
  if (cashAmount + selection.applied <= 0) throw new Error("INVALID_PAYMENT_AMOUNT");
  const newPaidAmount = Number(studentRow.paidAmount || 0) + cashAmount + selection.applied;
  const now = new Date();
  if (appliedCredits.length) await db.update(studentSubscriptionCredits).set({ status: "applied", appliedAt: now }).where(sql`${studentSubscriptionCredits.id} IN (${sql.join(appliedCredits.map(credit => sql`${credit.id}`), sql`, `)})`);
  await db.update(students).set({ paidAmount: String(newPaidAmount), paid: newPaidAmount >= Number(groupRow.fee) }).where(and(eq(students.id, studentRow.id), eq(students.userId, userId), eq(students.workspace, workspace)));
  const collectionLabel = groupRow.collectionPeriod === "term" ? "ترم" : groupRow.collectionPeriod === "per_lesson" ? "حصة" : "شهرية";
  const description = `دفعة ${collectionLabel} — ${groupRow.name}${selection.applied ? ` + خصم نقاط ${selection.applied} ج.م` : ""}`;
  const result = await db.insert(financialTransactions).values({ userId, workspace, studentId: studentRow.id, groupId: groupRow.id, kind: "subscription", amount: String(cashAmount), paidAt: now, dueDate: null, description });
  await recordChange(userId, { category: "finance", action: "recorded", entityName: studentRow.name, details: `تحصيل ${cashAmount} ج.م مع رصيد مكافآت ${selection.applied} ج.م` });
  return { transactionId: Number(result[0].insertId), cashAmount, appliedCredit: selection.applied, paidAmount: newPaidAmount, settled: newPaidAmount >= Number(groupRow.fee) };
}
export async function createPersonalReminder(userId: number, input: { title: string; note?: string | null; remindAt: Date; recurrence: "once" | "daily" | "weekly" }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const result = await db.insert(personalReminders).values({ userId, title: input.title, note: input.note ?? null, remindAt: input.remindAt, recurrence: input.recurrence }); const id = Number(result[0].insertId); await recordChange(userId, { category: "settings", action: "created", entityName: input.title, details: "تم إنشاء تذكير شخصي" }); return id; }
export async function updatePersonalReminder(userId: number, id: number, input: Partial<{ title: string; note: string | null; remindAt: Date; recurrence: "once" | "daily" | "weekly"; completed: boolean }>) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const rows = await db.select({ id: personalReminders.id, title: personalReminders.title }).from(personalReminders).where(and(eq(personalReminders.id, id), eq(personalReminders.userId, userId))).limit(1); if (!rows[0]) throw new Error("REMINDER_NOT_FOUND"); await db.update(personalReminders).set(input).where(and(eq(personalReminders.id, id), eq(personalReminders.userId, userId))); await recordChange(userId, { category: "settings", action: "updated", entityName: input.title || rows[0].title, details: input.completed ? "تم إكمال التذكير" : "تم تعديل التذكير" }); return true; }
export async function deletePersonalReminder(userId: number, id: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const rows = await db.select({ title: personalReminders.title }).from(personalReminders).where(and(eq(personalReminders.id, id), eq(personalReminders.userId, userId))).limit(1); if (!rows[0]) throw new Error("REMINDER_NOT_FOUND"); await db.delete(personalReminders).where(and(eq(personalReminders.id, id), eq(personalReminders.userId, userId))); await recordChange(userId, { category: "settings", action: "deleted", entityName: rows[0].title, details: "تم حذف التذكير" }); return true; }
export async function listDuePersonalReminders(now = new Date()) { const db = await getDb(); if (!db) return []; const rows = await db.select().from(personalReminders).where(and(eq(personalReminders.completed, false), lte(personalReminders.remindAt, now))); return rows.filter(row => shouldDeliverPersonalReminder(row.recurrence, row.lastDeliveredAt)); }
export async function claimPersonalReminderDelivery(id: number, now = new Date()) { const db = await getDb(); if (!db) return undefined; const row = (await db.select().from(personalReminders).where(and(eq(personalReminders.id, id), eq(personalReminders.completed, false), lte(personalReminders.remindAt, now))).limit(1))[0]; if (!row || !shouldDeliverPersonalReminder(row.recurrence, row.lastDeliveredAt)) return undefined; const nextRemindAt = getNextReminderDate(row.remindAt, row.recurrence); await db.update(personalReminders).set(nextRemindAt ? { remindAt: nextRemindAt, lastDeliveredAt: now } : { lastDeliveredAt: now }).where(and(eq(personalReminders.id, id), eq(personalReminders.completed, false), eq(personalReminders.remindAt, row.remindAt), isNull(personalReminders.lastDeliveredAt))); return row; }
export async function getOwnedCenter(userId: number) { const db = await getDb(); if (!db) return null; const rows = await db.select().from(centers).where(eq(centers.ownerUserId, userId)).limit(1); return rows[0] ?? null; }
export async function listCenterMembers(userId: number) { const db = await getDb(); if (!db) return []; const center = await getOwnedCenter(userId); if (!center) return []; return db.select().from(centerMembers).where(eq(centerMembers.centerId, center.id)).orderBy(desc(centerMembers.createdAt)); }
export const assistantPermissions = ["attendance", "finance"] as const;
export type CenterPermission = typeof assistantPermissions[number];
export type CenterScope = { dataUserId: number; role: "owner" | "teacher" | "assistant"; permissions: CenterPermission[]; center: typeof centers.$inferSelect | null };
export async function getCenterScope(userId: number): Promise<CenterScope> { const db = await getDb(); const owned = await getOwnedCenter(userId); if (owned) return { dataUserId: userId, role: "owner", permissions: [...assistantPermissions], center: owned }; if (!db) return { dataUserId: userId, role: "teacher", permissions: [...assistantPermissions], center: null }; const member = (await db.select().from(centerMembers).where(eq(centerMembers.userId, userId)).orderBy(desc(centerMembers.createdAt)).limit(1))[0]; if (!member) return { dataUserId: userId, role: "teacher", permissions: [...assistantPermissions], center: null }; const center = (await db.select().from(centers).where(eq(centers.id, member.centerId)).limit(1))[0] ?? null; if (!center) return { dataUserId: userId, role: "teacher", permissions: [...assistantPermissions], center: null }; let permissions: CenterPermission[] = [...assistantPermissions]; try { const parsed = JSON.parse(member.permissionsJson || "[]"); if (Array.isArray(parsed)) permissions = parsed.filter((value): value is CenterPermission => value === "attendance" || value === "finance"); } catch { /* use defaults */ } return { dataUserId: center.ownerUserId, role: member.role, permissions, center }; }
export function canCenterAction(scope: CenterScope, action: CenterPermission | "manage") { return scope.role === "owner" || scope.role === "teacher" || (action !== "manage" && scope.permissions.includes(action)); }
export async function createOwnedCenter(userId: number, input: { name: string; phone?: string | null; address?: string | null }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const existing = await getOwnedCenter(userId); if (existing) { await db.update(centers).set(input).where(eq(centers.id, existing.id)); return { ...existing, ...input }; } const result = await db.insert(centers).values({ ownerUserId: userId, name: input.name, phone: input.phone ?? null, address: input.address ?? null }); const center = { id: Number(result[0].insertId), ownerUserId: userId, name: input.name, phone: input.phone ?? null, address: input.address ?? null }; await db.insert(centerMembers).values({ centerId: center.id, userId, role: "owner", permissionsJson: JSON.stringify(assistantPermissions) }); return center; }
export async function addCenterMember(ownerUserId: number, input: { phone: string; role: "teacher" | "assistant"; permissions: CenterPermission[] }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const center = await getOwnedCenter(ownerUserId); if (!center) throw new Error("CENTER_NOT_FOUND"); const account = await getTeacherAccountByPhone(input.phone); if (!account) throw new Error("TEACHER_ACCOUNT_NOT_FOUND"); if (account.userId === ownerUserId) throw new Error("OWNER_ALREADY_MEMBER"); const existing = (await db.select().from(centerMembers).where(and(eq(centerMembers.centerId, center.id), eq(centerMembers.userId, account.userId))).limit(1))[0]; const values = { role: input.role, permissionsJson: JSON.stringify(input.role === "assistant" ? input.permissions : assistantPermissions) }; if (existing) await db.update(centerMembers).set(values).where(eq(centerMembers.id, existing.id)); else await db.insert(centerMembers).values({ centerId: center.id, userId: account.userId, ...values }); await recordChange(ownerUserId, { category: "settings", action: "updated", entityName: "فريق المركز", details: `تمت إضافة ${input.role === "assistant" ? "مساعد" : "مدرس"} إلى المركز` }); return { userId: account.userId, ...values }; }
export async function removeCenterMember(ownerUserId: number, memberId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const center = await getOwnedCenter(ownerUserId); if (!center) throw new Error("CENTER_NOT_FOUND"); await db.delete(centerMembers).where(and(eq(centerMembers.id, memberId), eq(centerMembers.centerId, center.id), ne(centerMembers.role, "owner"))); await recordChange(ownerUserId, { category: "settings", action: "updated", entityName: "فريق المركز", details: "تم إلغاء وصول عضو من الفريق" }); return true; }
export async function getCenterOverview(ownerUserId: number) { const [center, groups, studentRows, transactions, members] = await Promise.all([getOwnedCenter(ownerUserId), listGroups(ownerUserId), listStudents(ownerUserId), listTransactions(ownerUserId), listCenterMembers(ownerUserId)]); const income = transactions.filter(row => row.kind === "subscription" && row.paidAt).reduce((sum, row) => sum + Number(row.amount), 0); const expenses = transactions.filter(row => row.kind === "expense").reduce((sum, row) => sum + Number(row.amount), 0); return { center, groupsCount: groups.length, studentsCount: studentRows.length, membersCount: members.length, income, expenses, net: income - expenses, outstanding: studentRows.filter(row => !row.paid).length, members }; }
export async function listAssessments(userId: number, workspace?: Workspace) { const db = await getDb(); if (!db) return []; return db.select().from(assessments).where(workspace ? and(eq(assessments.userId, userId), eq(assessments.workspace, workspace)) : eq(assessments.userId, userId)).orderBy(desc(assessments.createdAt)); }
export async function createAssessment(userId: number, input: Omit<typeof assessments.$inferInsert, "userId" | "id" | "workspace">, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedStudentAndGroup(userId, workspace, input.studentId, input.groupId); const result = await db.insert(assessments).values({ ...input, workspace, userId }); const id = Number(result[0].insertId); const score = Number(input.score); const maxScore = Number(input.maxScore); if (Number.isFinite(score) && Number.isFinite(maxScore) && maxScore > 0 && score / maxScore >= 0.85) await awardStudentPoints(userId, { studentId: input.studentId, source: "high_score", points: 10, note: `درجة مميزة في ${input.title}`, referenceKey: `assessment:${id}` }); await recordChange(userId, { category: "assessment", action: "recorded", entityName: input.title, details: "تم رصد تقييم للطالب" }); return { id, ...input, workspace, userId }; }
export async function listBehaviorRecords(userId: number, workspace?: Workspace) { const db = await getDb(); if (!db) return []; return db.select().from(behaviorRecords).where(workspace ? and(eq(behaviorRecords.userId, userId), eq(behaviorRecords.workspace, workspace)) : eq(behaviorRecords.userId, userId)).orderBy(desc(behaviorRecords.createdAt)); }
export async function createBehaviorRecord(userId: number, input: Omit<typeof behaviorRecords.$inferInsert, "userId" | "id" | "workspace">, workspace: Workspace = "center") { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await ensureOwnedStudentAndGroup(userId, workspace, input.studentId, input.groupId); const result = await db.insert(behaviorRecords).values({ ...input, workspace, userId }); return { id: Number(result[0].insertId), ...input, workspace, userId }; }
